#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/mgmt/mcumgr/smp_client.h>
#include <smp_client_internal.h>

/* Sample SMP address */
#define SMP_CLIENT_ADDRESS "1.1.1.1"

static K_SEM_DEFINE(smp_client_sem, 0, 1);
static int smp_client_status;
static struct smp_client_object smp_client;

static void smp_client_cb(struct smp_client_object *smp_client, int status, void *user_data)
{
	k_sem_give(&smp_client_sem);
	smp_client_status = status;
}

static void *smp_client_suite_setup(void)
{
	smp_client_status = 1;
	smp_client_object_init(&smp_client, smp_client_cb, NULL);

	return NULL;
}

static void smp_client_before(void *fixture)
{
	smp_client_status = 1;
	k_sem_reset(&smp_client_sem);
}

/* This test can only be run with the dummy L2 driver */
static bool predicate(const void *arg)
{
	ARG_UNUSED(arg);

	if (!IS_ENABLED(CONFIG_NET_L2_DUMMY)) {
		printk("SMP client test requires dummy L2 driver, skipping\n");
		return false;
	}

	return true;
}

ZTEST_SUITE(smp_client_tests, predicate, smp_client_suite_setup, smp_client_before, NULL, NULL);

ZTEST(smp_client_tests, test_init)
{
	zassert_equal(smp_client.cb, smp_client_cb, "Callback not set correctly");
	zassert_is_null(smp_client.user_data, "User data not NULL");
	zassert_equal(smp_client.retries, CONFIG_MCUMGR_SMP_CLIENT_RETRIES,
		      "Incorrect retry count");
}

ZTEST(smp_client_tests, test_tx_lockup)
{
	int ret;

	smp_client.tx_lock = true;
	ret = smp_client_send_cmd(&smp_client, SMP_CLIENT_ADDRESS, 0, NULL, 0);
	zassert_equal(ret, -EAGAIN, "Incorrect status for locked TX");
	smp_client.tx_lock = false;
}
